---programmuebersicht.ts---
import { Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { VeranstaltungenService } from '../shared/api/veranstaltungen.service';
import { Veranstaltung } from '../shared/models/veranstaltung';
import { EventCard } from '../shared/ui/event-card/event-card';

type Ladezustand = 'laedt' | 'geladen' | 'fehler';

@Component({
  selector: 'app-programmuebersicht',
  imports: [EventCard],
  templateUrl: './programmuebersicht.html',
  styleUrl: './programmuebersicht.scss'
})
export class Programmuebersicht {
  private readonly veranstaltungenService = inject(VeranstaltungenService);

  readonly ladezustand = signal<Ladezustand>('laedt');
  readonly veranstaltungen = signal<Veranstaltung[]>([]);

  protected readonly skeletonPlatzhalter = [0, 1, 2, 3];

  constructor() {
    this.veranstaltungenService
      .getVeranstaltungen()
      .pipe(takeUntilDestroyed())
      .subscribe({
        next: (veranstaltungen) => {
          this.veranstaltungen.set(veranstaltungen);
          this.ladezustand.set('geladen');
        },
        error: () => {
          this.ladezustand.set('fehler');
        }
      });
  }
}
---programmuebersicht.html---
<main class="programmuebersicht">
  <h1 class="programmuebersicht__titel">Programm</h1>

  @if (ladezustand() === 'laedt') {
    <div class="programmuebersicht__liste" aria-busy="true" aria-label="Veranstaltungen werden geladen">
      @for (platzhalter of skeletonPlatzhalter; track platzhalter) {
        <div class="event-card-skeleton">
          <div class="event-card-skeleton__titel"></div>
          <div class="event-card-skeleton__meta"></div>
        </div>
      }
    </div>
  } @else if (ladezustand() === 'fehler') {
    <p class="programmuebersicht__fehler" role="alert">
      Veranstaltungen konnten nicht geladen werden. Bitte versuchen Sie es später erneut.
    </p>
  } @else if (veranstaltungen().length === 0) {
    <p class="programmuebersicht__leerzustand">Aktuell sind keine Veranstaltungen verfügbar.</p>
  } @else {
    <div class="programmuebersicht__liste">
      @for (veranstaltung of veranstaltungen(); track veranstaltung.id) {
        <app-event-card [veranstaltung]="veranstaltung" />
      }
    </div>
  }
</main>
